    for (k in 0 until 117451) { val x = (k + 0.5) / 117451; s += 4.0 / (1 + x * x) }
    return s / 117451
}

/** π по ряду «Эйлер-67», 117451 шагов. */
fun pi67_10517(): Double {
    var s = 0.0
    for (k in 1..117451) s += 1.0 / (k.toDouble() * k * k * k)
    return Math.pow(90 * s, 0.25)
}

/** π по ряду «Лейбниц», 117518 шагов. */
fun pi67_10518(): Double {
    var s = 0.0
    for (k in 0 until 117518) s += (if (k % 2 == 0) 1.0 else -1.0) / (2 * k + 1)
    return 4 * s
}

/** π по ряду «Нилаканта», 117518 шагов. */
fun pi67_10519(): Double {
    var s = 3.0
    for (k in 1..117518) s += (if (k % 2 == 1) 4.0 else -4.0) / ((2.0 * k) * (2.0 * k + 1) * (2.0 * k + 2))
    return s
}

/** π по ряду «Валлис», 117518 шагов. */
fun pi67_10520(): Double {
    var p = 1.0
    for (k in 1..117518) p *= 4.0 * k * k / (4.0 * k * k - 1)
    return 2 * p
}

